const G=Game,$=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n),compact=n=>new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);let jobSector='',jobQuery='';let state=G.fresh(),page='overview',category='Immobilien',holding=false,lastFrame=performance.now(),saveTime=0,toastTimer,saveFailed=false;
try{let raw=localStorage.getItem('kapital-v1');if(raw){let saved=JSON.parse(raw);if(G.valid(saved)){state=saved;let result=G.catchUp(state);if(result.seconds>15)G.log(state,'Hintergrund · '+Math.floor(result.seconds/60)+' Minuten abgerechnet',result.change);}}}catch{saveFailed=true;}
const NAV=[['overview','◫','Übersicht'],['career','↗','Karriere'],['stocks','⌁','Börse'],['assets','▦','Besitz'],['credit','◎','Finanzen']];
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){try{localStorage.setItem('kapital-v1',JSON.stringify(state));}catch{if(!saveFailed)toast('Speichern nicht verfügbar. Bitte Spielstand exportieren.');saveFailed=true;}}
function action(error,success){toast(error||success);save();render();}
function modal(html){holding=false;$('#modalContent').innerHTML=html;$('#modal').showModal();}
function intro(title,desc){return `<div class="intro"><div><h1>${title}</h1><p>${desc}</p></div><span class="badge">● Fiktive Simulation</span></div>`;}
function stats(){return `<div class="stats"><div class="stat"><div class="label">Gesamtvermögen <span style="float:right">↗</span></div><div class="value" data-value="net">${money(G.net(state))}</div><div class="sub">Besitz zum Verkaufswert · abzüglich Schulden</div></div><div class="stat"><div class="label">Verfügbares Guthaben</div><div class="value" data-value="cash">${money(state.cash)}</div><div class="sub">Dein virtuelles ${state.bank}-Konto</div></div><div class="stat"><div class="label">Monatlicher Überschuss</div><div class="value" data-value="income">${compact(monthly())}</div><div class="sub positive">Gehalt + Besitz − Kreditraten</div></div></div>`;}
function monthly(){return G.salary(state)+G.passive(state)-state.loans.reduce((n,l)=>n+l.payment,0);}
function chart(){let h=state.history.length>1?state.history:[G.net(state),G.net(state)];let min=Math.min(...h),max=Math.max(...h),range=Math.max(100,max-min);let pts=h.map((v,i)=>[i*500/(h.length-1),140-(v-min)/range*115]);let path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');return `<div class="chart"><svg viewBox="0 0 500 160" preserveAspectRatio="none" role="img" aria-label="Verlauf deines Nettovermögens"><defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a4c66e" stop-opacity=".35"/><stop offset="1" stop-color="#a4c66e" stop-opacity="0"/></linearGradient></defs><path d="M0 30H500 M0 80H500 M0 130H500" stroke="#e9ede4" fill="none"/><path d="${path} L500,160 L0,160 Z" fill="url(#fade)"/><path d="${path}" fill="none" stroke="#739655" stroke-width="3"/></svg></div><div class="chart-labels"><span>Letzte Spielstunden</span><span>Jetzt</span></div>`;}
function overview(){return intro('Dein nächster Zug.','Klein anfangen. Klug investieren. Groß denken.')+stats()+`<div class="dashboard"><section class="panel"><div class="panel-head"><h2>Deine Bankkarte</h2><button class="secondary" data-do="bank" style="padding:7px 11px;font-size:11px">Bank wechseln ↗</button></div><button class="bankcard" id="earn" aria-label="Gedrückt halten, um virtuelles Geld zu verdienen"><span class="card-top">${state.bank}<small>SIMULATION</small></span><span class="chip">▥ ≋</span><span class="card-number">•••• &nbsp; •••• &nbsp; •••• &nbsp; 2048</span><span class="card-bottom"><span>DEIN VIRTUELLES KONTO</span><span>KAPITAL ↗</span></span></button><p class="hold-hint">◎ Finger auf der Karte halten, um zu verdienen</p><p class="rate">+ ${money(.2+G.salary(state)/25000)} / Sekunde · auch mit Leertaste</p></section><section class="panel"><div class="panel-head"><h2>Vermögensentwicklung</h2><span class="eyebrow">LIVE</span></div><div class="label">Dein Fortschritt, Schritt für Schritt.</div>${chart()}<div class="income"><span>Passives Einkommen / Spielmonat</span><strong class="positive">${compact(G.passive(state))}</strong></div></section><section class="panel wide"><div class="panel-head"><h2>Was kommt als Nächstes?</h2><span class="eyebrow">DEINE MÖGLICHKEITEN</span></div><div class="quickgrid"><button class="quick" data-page="career"><span class="icon">↗</span><span>Karriere starten<small>${state.job<0?'Dein erstes regelmäßiges Einkommen':G.JOBS[state.job].name+' · nächste Stufe entdecken'}</small></span></button><button class="quick" data-page="stocks"><span class="icon">⌁</span><span>In den Markt einsteigen<small>Schon mit einem Anteil dabei</small></span></button><button class="quick" data-page="assets"><span class="icon">▦</span><span>Besitz aufbauen<small>Von der Garage bis zur eigenen Insel</small></span></button></div></section><section class="panel wide"><div class="panel-head"><h2>Letzte Bewegungen</h2><span class="eyebrow">KONTOJOURNAL</span></div>${state.events.slice(0,5).map(e=>`<div class="activity"><span>${esc(e.text)}</span><strong class="${e.amount>=0?'positive':'debt'}">${e.amount?money(e.amount):'✓'}</strong></div>`).join('')}</section></div>`;}
function career(){return intro('Dein Weg nach oben.','Bewirb dich, sammle Erfahrung und verbessere dein Einkommen.')+`<section class="panel" style="margin-bottom:22px"><h2>${state.job>=0?G.JOBS[state.job].name:'Bereit für den ersten Job?'}</h2><p class="note">${state.job<0?'Als Aushilfe kannst du sofort kostenlos starten.':'Dein Gehalt fließt automatisch, auch bei geschlossenem Spiel ohne Zeitlimit.'} Erfahrung: <strong id="xp">${Math.floor(state.xp)} XP</strong> · 1 XP pro 10 Sekunden Kartenhalten.</p></section>`+`<div class="job-filters"><div><label for="jobSearch">${G.JOBS.length} Jobs · Beruf suchen</label><input id="jobSearch" placeholder="Zum Beispiel Pilot oder Pflege" value="${esc(jobQuery)}"></div><div><label for="jobSector">Branche</label><select id="jobSector"><option value="">Alle Branchen</option>${[...new Set(G.JOBS.map(j=>j.sector))].map(v=>`<option ${v===jobSector?'selected':''}>${v}</option>`).join('')}</select></div></div><p class="note">Immer genau eine aktive Stelle. Du kannst den Beruf wechseln, auch zu einem niedrigeren Gehalt. Gehälter sind fiktive Netto-Spielwerte pro Spielmonat.</p>`+G.JOBS.map((j,i)=>({...j,index:i})).filter(j=>(!jobSector||j.sector===jobSector)&&(!jobQuery||j.name.toLocaleLowerCase('de').includes(jobQuery.toLocaleLowerCase('de')))).sort((a,b)=>a.pay-b.pay).map(j=>{let i=j.index;return `<section class="panel job"><div><h3>${j.name} ${i===state.job?'· Aktuelle Stelle':''}</h3><p>${j.sector} · ${compact(j.pay)} netto / Spielmonat · ${j.xp} XP benötigt<br>${j.cost?compact(j.cost)+' einmalige Weiterbildung vor Bewerbung':'Keine Bewerbungskosten'}</p></div><button data-apply="${i}" ${i===state.job?'disabled':''}>${i===state.job?'Angestellt':'Bewerben ↗'}</button></section>`;}).join('');}
function stocks(){return intro('Chancen erkennen.','Fiktive Unternehmen. Simulierte Kurse. Deine Strategie.')+`<p class="note">Kurse ändern sich alle 30 Sekunden und können steigen oder fallen. Handelsgebühr: 0,5 % pro Kauf und Verkauf. Kein garantierter Gewinn. Kein Bezug zu echten Wertpapieren.</p><div class="grid">`+G.STOCKS.map(a=>`<section class="panel"><div class="eyebrow">${a.symbol} · SIMULIERTER MARKT</div><h3 style="margin-top:14px">${a.name}</h3><div class="asset-price" data-price="${a.id}">${money(state.prices[a.id])}</div><p class="note">${state.shares[a.id]||0} Anteile im Depot<br>Schwankung: ${a.risk>.05?'Hoch':'Moderat'}</p><div class="actions"><button data-trade="${a.id}:1">Kaufen</button><button class="secondary" data-trade="${a.id}:-1">Verkaufen</button></div></section>`).join('')+'</div>';}
function assets(){let cats=[...new Set(G.ASSETS.map(a=>a.category))];return intro('Ein Stück deiner Zukunft.','Investiere in Werte, die zu deinem Plan passen.')+`<div class="tabs">${cats.map(c=>`<button class="${c===category?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="grid">`+G.ASSETS.filter(a=>a.category===category).map(a=>`<article class="panel asset"><div class="asset-art">${a.icon}</div><div class="asset-body"><span class="eyebrow">${a.category} · ${state.owned[a.id]||0} IM BESITZ</span><h3>${a.name}</h3><p>${a.description}</p><div class="asset-price">${compact(a.price)}</div><div class="sub ${a.income>=0?'positive':'debt'}">${a.income>=0?'+':''}${compact(a.income)} / Spielmonat</div><div class="actions" style="margin-top:18px"><button data-buy="${a.id}">Kaufen</button><button class="secondary" data-finance="${a.id}">Finanzieren</button>${state.owned[a.id]?`<button class="secondary" data-sell="${a.id}">Verkaufen · 90 %</button>`:''}</div></div></article>`).join('')+`</div><p class="note">Finanzierung: 30 % Eigenkapital, 60 Spielmonate Laufzeit, 6,5 % nominaler Jahreszins. Besitz wird beim Verkauf mit 10 % Abschlag bewertet. Kredite laufen nach einem Verkauf weiter.</p>`;}
function credit(){let available=Math.max(0,G.limit(state)-G.debt(state));return intro('Wachstum mit Augenmaß.','Behalte deine Raten und deinen finanziellen Spielraum im Blick.')+stats()+`<div class="dashboard"><section class="panel"><h2>Dein Kreditrahmen</h2><div class="asset-price">${compact(available)}</div><p class="note">6,5 % nominaler Jahreszins · 36 Spielmonate. Alle Kreditraten zusammen dürfen höchstens 40 % deines monatlichen Einkommens ausmachen. Zinsen werden auf die Restschuld berechnet.</p><form id="loanForm"><label for="loanAmount">Gewünschter Kreditbetrag (€)</label><input id="loanAmount" name="amount" type="number" min="100" step="100" value="1000" required><button>Kredit aufnehmen</button></form><p class="note">Kein Gehalt? Starte zuerst unter „Karriere“. Wenn dein Guthaben nicht für Raten reicht, bleibt die Restschuld mit Zinsen bestehen.</p></section><section class="panel"><h2>Laufende Finanzierungen</h2>${state.loans.length?state.loans.map((l,i)=>`<div class="activity"><div><strong>${esc(l.purpose)}</strong><p class="note">Restschuld ${money(l.balance)}<br>Rate ${money(l.payment)} / Monat</p><button class="secondary" data-repay="${i}">Komplett tilgen</button></div></div>`).join(''):'<div class="empty">◎<p style="margin-top:15px">Du bist schuldenfrei.</p></div>'}</section></div>`;}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function render(){holding=false;$('#nav').innerHTML=NAV.map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><i>${icon}</i>${label}</button>`).join('');$('#view').innerHTML=({overview,career,stocks,assets,credit}[page])();update();bindHold();}
function update(){let vals={net:G.net(state),cash:state.cash,income:monthly()};document.querySelectorAll('[data-value]').forEach(el=>el.textContent=el.dataset.value==='income'?compact(vals.income):money(vals[el.dataset.value]));$('#date').textContent=`Jahr ${1+Math.floor(state.elapsed/(G.MONTH*12))} · Monat ${1+Math.floor(state.elapsed/G.MONTH)%12}`;if($('#xp'))$('#xp').textContent=Math.floor(state.xp)+' XP';document.querySelectorAll('[data-price]').forEach(el=>el.textContent=money(state.prices[el.dataset.price]));}
function bindHold(){let b=$('#earn');if(!b)return;const end=()=>{holding=false;b.classList.remove('holding');};b.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();b.setPointerCapture(e.pointerId);holding=true;b.classList.add('holding');});for(let ev of ['pointerup','pointercancel','lostpointercapture','blur'])b.addEventListener(ev,end);b.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();holding=true;b.classList.add('holding');}});b.addEventListener('keyup',end);b.addEventListener('contextmenu',e=>e.preventDefault());}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.page){page=d.page;render();window.scrollTo(0,0);}if(d.category){category=d.category;render();}if(d.apply!==undefined)action(G.apply(state,+d.apply),'Bewerbung erfolgreich! Dein Gehalt läuft jetzt.');if(d.buy)action(G.buy(state,d.buy),'Gekauft! Dein Besitz wurde aktualisiert.');if(d.sell)action(G.sell(state,d.sell),'Besitz verkauft.');if(d.finance){let a=G.ASSETS.find(a=>a.id===d.finance);modal(`<h2>${a.name} finanzieren</h2><p>Eigenkapital: ${money(a.price*.3)}<br>Kredit: ${money(a.price*.7)}<br>Laufzeit: 60 Spielmonate · Jahreszins: 6,5 %<br>Monatliche Rate: ${money(a.price*.7*(.065/12)/(1-Math.pow(1+.065/12,-60)))}</p><button data-confirmfinance="${a.id}">Verbindlich im Spiel kaufen</button>`);}if(d.confirmfinance){let err=G.buy(state,d.confirmfinance,true);$('#modal').close();action(err,'Finanzierung und Kauf abgeschlossen.');}if(d.trade){let [id,sign]=d.trade.split(':');modal(`<h2>Anteile ${+sign>0?'kaufen':'verkaufen'}</h2><p>Preis pro Anteil: ${money(state.prices[id])} · 0,5 % Gebühr. Der Ausführungskurs kann sich bis zur Bestätigung ändern.</p><form id="tradeForm" data-id="${id}" data-sign="${sign}"><label for="quantity">Stückzahl</label><input id="quantity" name="qty" type="number" value="1" min="1" step="1" required><button>Handel bestätigen</button></form>`);}if(d.repay!==undefined){let i=+d.repay,l=state.loans[i];if(state.cash<l.balance)toast('Dein Guthaben reicht zur vollständigen Tilgung noch nicht.');else{state.cash-=l.balance;G.log(state,'Kredit getilgt',-l.balance);state.loans.splice(i,1);action('','Kredit vollständig getilgt.');}}if(d.do==='bank'){modal(`<h2>Deine virtuelle Bank</h2><p>Wähle den Banknamen für deine Spielkarte. Alle Banken haben im Spiel dieselben Konditionen. Keine echten Konten, Logos oder Bankverbindungen.</p><label for="bankSelect">Bank</label><select id="bankSelect">${G.BANKS.map(n=>`<option ${state.bank===n?'selected':''}>${n}</option>`).join('')}</select><button data-do="choosebank">Bank auswählen</button>`);}if(d.do==='choosebank'){state.bank=$('#bankSelect').value;$('#modal').close();action('','Virtuelle Bank gewechselt.');}if(b.classList.contains('close'))$('#modal').close();if(d.do==='export'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='kapital-spielstand.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}if(d.do==='reset'){modal('<h2>Wirklich neu anfangen?</h2><p>Dein jetziger Spielstand wird überschrieben. Exportiere ihn vorher, wenn du ihn behalten möchtest.</p><button data-do="confirmreset">Spielstand zurücksetzen</button>');}if(d.do==='confirmreset'){state=G.fresh();save();$('#modal').close();render();toast('Neues Spiel gestartet.');}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='loanForm')action(G.loan(state,+new FormData(e.target).get('amount')),'Virtueller Kredit ausgezahlt.');if(e.target.id==='tradeForm'){let f=e.target;let err=G.trade(state,f.dataset.id,+new FormData(f).get('qty')*+f.dataset.sign);$('#modal').close();action(err,'Handel ausgeführt.');}});
$('#settings').onclick=()=>modal(`<h2>Dein Spiel. Dein Tempo.</h2><p>Ein Spielmonat dauert 12 echte Minuten. Gehalt, Mieten, Betriebskosten und Kreditraten werden laufend verrechnet. Auch bei geschlossenem Spiel werden Gehalt, Besitzerträge, Unterhalt und Kreditraten für die gesamte vergangene Zeit nachberechnet, sobald du zurückkommst. Dafür muss die App im Hintergrund nicht geöffnet bleiben. Börsenkurse bleiben während deiner Abwesenheit unverändert. Gedrückthalten gibt zusätzliches Einkommen und Erfahrung.</p><p>Automatischer Speicherstand auf diesem Gerät. Für ein anderes Gerät kannst du deinen Stand exportieren und importieren.</p><button data-do="export">Spielstand exportieren</button><label for="import" style="display:block;margin-top:20px">Spielstand importieren</label><input type="file" id="import" accept="application/json"><button class="secondary" data-do="reset">Neues Spiel</button><p>Unabhängige fiktive Simulation. Banknamen dienen allein der Auswahl; keine Zugehörigkeit, echten Finanzprodukte oder echten Transaktionen. Preise und Renditen sind Spielparameter.</p>`);
document.addEventListener('change',async e=>{if(e.target.id!=='import'||!e.target.files[0])return;try{let file=e.target.files[0];if(file.size>100000)throw Error();let parsed=JSON.parse(await file.text());if(!G.valid(parsed))throw Error();state=parsed;state.last=Date.now();save();$('#modal').close();render();toast('Spielstand geladen.');}catch{toast('Diese Datei ist kein gültiger KAPITAL-Spielstand.');}});
window.addEventListener('blur',()=>holding=false);document.addEventListener('visibilitychange',()=>{holding=false;if(document.hidden){state.last=Date.now();save();}else{let result=G.catchUp(state);if(result.seconds>15){G.log(state,'Hintergrund-Einkommen abgerechnet',result.change);toast('Willkommen zurück: '+money(result.change)+' Veränderung deines Guthabens.');save();render();}lastFrame=performance.now();update();}});window.addEventListener('pagehide',save);
setInterval(()=>{let now=performance.now(),dt=(now-lastFrame)/1000;lastFrame=now;if(document.hidden)return;if(dt>2){G.catchUp(state);}else{G.tick(state,dt,holding);}update();if(now-saveTime>3000){save();saveTime=now;}},100);render();if(saveFailed)toast('Speicher nicht verfügbar. Bitte Spielstand regelmäßig exportieren.');

document.addEventListener('change',e=>{if(e.target.id==='jobSector'){jobSector=e.target.value;render();}if(e.target.id==='jobSearch'){jobQuery=e.target.value;render();}});
